#!/bin/bash# scripts/run_full_validation_pipeline.sh# Фиксированный алгоритм успешной валидации (v1.4)set -eecho "🚀 Запуск фиксированного контура TS-Validator (v1.4)..."echo "========================================================"# Переход в корень проектаcd "$(dirname "$0")/.."# Активация venv, если существуетif [ -d "venv" ]; then    source venv/bin/activatefi# Запуск проверенного pytest-набораecho "🔍 Запуск TS-Validator (pytest v1.4)..."python -m pytest tests/test_validator.py -v --tb=shortecho "========================================================"echo "✅ КОНТУР ЗАКРЫТ. Все слои прошли конституционную валидацию."